q=p.aD("      SELECT\n        NULLIF(MAX(COALESCE(h.referans,'')), '') AS referans,\n        CASE WHEN MAX(COALESCE(h.referans,'')) = '' THEN 0 ELSE 1 END\n          AS referansli,\n        MAX(h.tarih) AS tarih,\n        MIN(h.olusturma_zamani) AS olusturma_zamani,\n        -- 06.11 (eksik dosya incelemesi): \"Silinenler\" a\xe7\u0131kken AKT\u0130F fi\u015fin\n        -- toplamlar\u0131 yaln\u0131z aktif kalemlerden (d\xfczenleme art\u0131\u011f\u0131 silik sat\u0131rlar\n        -- say\u0131lmaz; GAZC540 ger\xe7ek 28 iken 83 g\xf6r\xfcn\xfcyordu). Tamamen silik\n        -- fi\u015fte t\xfcm sat\u0131rlar. Silinenler kapal\u0131yken sonu\xe7 ayn\u0131.\n        CASE WHEN MIN(COALESCE(h.silindi,0)) = 0\n             THEN COUNT(DISTINCT CASE WHEN COALESCE(h.silindi,0) = 0\n                                      THEN COALESCE(h.urun_id, -h.id) END)\n             ELSE COUNT(DISTINCT COALESCE(h.urun_id, -h.id)) END\n          AS urun_sayisi,\n        CASE WHEN MIN(COALESCE(h.silindi,0)) = 0 THEN COALESCE(SUM(CASE WHEN COALESCE(h.silindi,0) = 0 THEN CASE WHEN h.tip = 'giris' THEN h.miktar ELSE 0 END ELSE 0 END), 0) ELSE COALESCE(SUM(CASE WHEN h.tip = 'giris' THEN h.miktar ELSE 0 END), 0) END\n          AS giren,\n        CASE WHEN MIN(COALESCE(h.silindi,0)) = 0 THEN COALESCE(SUM(CASE WHEN COALESCE(h.silindi,0) = 0 THEN CASE WHEN h.tip = 'cikis' THEN h.miktar ELSE 0 END ELSE 0 END), 0) ELSE COALESCE(SUM(CASE WHEN h.tip = 'cikis' THEN h.miktar ELSE 0 END), 0) END\n          AS cikan,\n        CASE WHEN MIN(COALESCE(h.silindi,0)) = 0 THEN COALESCE(SUM(CASE WHEN COALESCE(h.silindi,0) = 0 THEN h.miktar * COALESCE(h.birim_fiyat, 0) ELSE 0 END), 0) ELSE COALESCE(SUM(h.miktar * COALESCE(h.birim_fiyat, 0)), 0) END\n          AS toplam_tutar,\n        -- Onar\u0131mda firma = PROJE ADI (M10, 0.9.16): onar\u0131m fi\u015finde cari yok;\n        -- ar\u0131za kayd\u0131ndan proje ad\u0131 t\xfcretilir (g\xf6r\xfcn\xfcm, veri de\u011fi\u015fmez).\n        -- A-Z denetim (D2-6 kal\u0131b\u0131): cari/tip/a\xe7\u0131klama AKT\u0130F kalemlerden;\n        -- fi\u015f tamamen silikse t\xfcm sat\u0131rlara geri d\xfc\u015f\xfcl\xfcr (silinenler dahil\n        -- g\xf6r\xfcn\xfcmde d\xfczenleme art\u0131\u011f\u0131n\u0131n eski de\u011feri MAX ile s\u0131zmas\u0131n).\n        COALESCE(\n          CASE WHEN MIN(COALESCE(h.silindi,0)) = 0\n               THEN MAX(CASE WHEN COALESCE(h.silindi,0) = 0 THEN h.cari_ad END)\n               ELSE MAX(h.cari_ad) END,\n          MAX(ar.proje_adi)) AS cari_ad,\n        MAX((CASE WHEN h.referans LIKE 'AYT-%' THEN\n  (SELECT COALESCE(NULLIF(TRIM(sp.cari_ad),''), cr.ad)\n     FROM siparisler sp LEFT JOIN cariler cr ON cr.id = sp.cari_id\n    WHERE sp.no = SUBSTR(h.referans, 5)\n    ORDER BY COALESCE(sp.silindi,0), sp.id DESC LIMIT 1)\nEND)) AS ayirtma_cari_ad,\n        -- \u0130LK i\u015flemi yapan kullan\u0131c\u0131: grubun EN ESK\u0130 (MIN olusturma_zamani)\n        -- sat\u0131r\u0131ndaki kullanici_ad \u2014 d\xfcz MAX() edit\xf6rce ezilmi\u015f eski veride\n        -- yanl\u0131\u015f ad\u0131 se\xe7ebiliyordu. '~' ayrac\u0131 ISO zaman damgas\u0131nda ge\xe7mez;\n        -- olusturma_zamani NULL sat\u0131rlar '9999' ile sona at\u0131l\u0131r.\n        NULLIF(SUBSTR(\n          MIN(COALESCE(h.olusturma_zamani,'9999') || '~' ||\n              COALESCE(h.kullanici_ad,'')),\n          INSTR(MIN(COALESCE(h.olusturma_zamani,'9999') || '~' ||\n              COALESCE(h.kullanici_ad,'')), '~') + 1\n        ), '') AS kullanici_ad,\n        NULLIF(MAX(COALESCE(h.duzelten_ad,'')), '') AS duzelten_ad,\n        CASE WHEN MIN(COALESCE(h.silindi,0)) = 0\n             THEN MAX(CASE WHEN COALESCE(h.silindi,0) = 0 THEN h.hareket_tipi END)\n             ELSE MAX(h.hareket_tipi) END AS hareket_tipi,\n        -- 29.09 (\u0130\u015flem Tipi Ayr\u0131nt\u0131): fi\u015fte AKT\u0130F kalemlerin farkl\u0131\n        -- hareket_tipi say\u0131s\u0131; >1 ise ekran \"Kar\u0131\u015f\u0131k\" g\xf6sterir (MAX tek\n        -- de\u011feri yan\u0131ltmas\u0131n). Tamamen silik fi\u015fte 0.\n        -- Etiket k\xfcmesiyle hizal\u0131: bilinmeyen/bo\u015f/'diger' tek \"Di\u011fer\" say\u0131l\u0131r.\n        COUNT(DISTINCT CASE WHEN COALESCE(h.silindi,0) = 0 THEN\n            CASE WHEN h.hareket_tipi IN ('alis','satis','iade','sayim',\n                                         'transfer','onarim','irsaliye')\n                 THEN h.hareket_tipi ELSE 'diger' END END)\n          AS hareket_tipi_cesit,\n        CASE WHEN MIN(COALESCE(h.silindi,0)) = 0\n             THEN MAX(CASE WHEN COALESCE(h.silindi,0) = 0 THEN h.aciklama END)\n             ELSE MAX(h.aciklama) END AS aciklama,\n        -- v101.3: proje AKT\u0130F kalemlerden (d\xfczenleme art\u0131\u011f\u0131 eski ad\u0131 ezmesin).\n        MAX(CASE WHEN COALESCE(h.silindi,0) = 0 THEN h.proje END) AS proje,\n        CASE WHEN MAX(COALESCE(h.hareket_tipi,'')) = 'transfer'\n             THEN 'transfer' ELSE MAX(h.tip) END AS tip,\n        COALESCE(MAX(s.ad), MAX(sar.ad)) AS sube_ad,\n        MAX(CASE WHEN COALESCE(h.hareket_tipi,'') != 'transfer'\n                 THEN d.ad END) AS depo_ad,\n        MAX(CASE WHEN h.hareket_tipi = 'transfer' AND h.tip = 'cikis'\n                 THEN d.ad END) AS kaynak_depo,\n        MAX(CASE WHEN h.hareket_tipi = 'transfer' AND h.tip = 'giris'\n                 THEN d.ad END) AS hedef_depo,\n        -- Fi\u015f ancak T\xdcM kalemleri silindi=1 ise S\u0130L\u0130NM\u0130\u015eT\u0130R (GAZG001 kal\u0131b\u0131).\n        MIN(COALESCE(h.silindi,0)) AS silindi,\n        MAX(h.id) AS id,\n        MAX(h.miktar) AS miktar,\n        MAX(h.birim_fiyat) AS birim_fiyat,\n        MAX(COALESCE(u.ad,        h.urun_ad))   AS urun_ad,\n        MAX(COALESCE(u.urun_kodu, h.urun_kodu)) AS urun_kodu\n      FROM stok_hareketler h\n      LEFT JOIN urunler u ON h.urun_id = u.id\n      LEFT JOIN subeler s ON h.sube_id = s.id\n      LEFT JOIN depolar d ON h.depo_id = d.id\n      LEFT JOIN ariza_kayitlari ar ON h.referans = 'ariza:' || ar.id\n      LEFT JOIN subeler sar ON sar.id = ar.sube_id\n      WHERE "+o.a+"\n      GROUP BY CASE WHEN h.referans IS NULL OR h.referans = ''\n                    THEN 'id:' || h.id ELSE 'ref:' || h.referans END\n      ORDER BY\n        MAX(h.tarih) DESC,\n        CASE WHEN MAX(COALESCE(h.referans,'')) = '' THEN 1 ELSE 0 END,\n        MAX(h.referans) DESC,\n        MAX(h.id) DESC\n      LIMIT 10000\n    ",m)
